const SKIPPED_LIMIT: usize = 5000;
const TECHNOLOGY_CAPTURE_LIMIT: usize = 512;
const TECHNOLOGY_CAPTURE_BYTES: usize = 16 * 1024 * 1024;
const OBSERVED_SURFACE_LIMIT: usize = 2048;
