struct CrawlScope {
    hostname: String,
    ip: bool,
}

impl CrawlScope {
    fn new(hostname: &str) -> Self {
        let hostname = {
            let (hostname,): (&str,) = (hostname,);

            hostname
                .trim_matches(['[', ']'])
                .trim_end_matches('.')
                .to_ascii_lowercase()
        };
        let ip = hostname.parse::<IpAddr>().is_ok();
        let hostname = if ip {
            hostname
        } else {
            hostname
                .strip_prefix("www.")
                .unwrap_or(&hostname)
                .to_owned()
        };
        Self { hostname, ip }
    }

    fn allows(&self, hostname: &str) -> bool {
        let hostname = {
            let (hostname,): (&str,) = (hostname,);

            hostname
                .trim_matches(['[', ']'])
                .trim_end_matches('.')
                .to_ascii_lowercase()
        };
        hostname == self.hostname
            || (!self.ip
                && hostname
                    .strip_suffix(&self.hostname)
                    .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1))
    }
}

pub(super) fn hostname_in_scope(root_hostname: &str, hostname: &str) -> bool {
    CrawlScope::new(root_hostname).allows(hostname)
}

